import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import { create_list_edit_delete_asset_distributors } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
import DeleteDistributors from "@/components/Asset/Popups/DeleteDistributors.vue";
import AddDistributors from "@/components/Asset/Popups/AddDistributors.vue";
import EditDistributors from "@/components/Asset/Popups/EditDistributors.vue";
import BulkDistributors from "@/components/Asset/Bulkupload/BulkDistributors.vue";
import * as XLSX from "xlsx";
export default {
  components: {
    AddDistributors,
    EditDistributors,
    DeleteDistributors,
    SnackBar,
    BulkDistributors
  },
  emits: ["backAction"],
  data() {
    return {
      createdistributors: false,
      distributoredition: false,
      distributordeletion: false,
      SnackBarComponent: {},
      componentcheck: 0,
      fixed: true,
      distributorRecords: [],
      tableLoading: false,
      distributorItem: {},
      distributorHeaders: [{
        title: "Name",
        key: "asset_distributor_name",
        sortable: false
      }, {
        title: "Code",
        key: "asset_distributor_code",
        sortable: false
      }, {
        title: "Contact Name",
        key: "contact_name",
        sortable: false
      }, {
        title: "Email ID",
        key: "asset_distributor_email",
        sortable: false
      }, {
        title: "Contact No",
        key: "full_contact_no",
        sortable: false
      }, {
        title: "Actions",
        key: "actions",
        sortable: false
      }],
      currentPage: 1,
      itemsPerPage: 20,
      paginatedItems: [],
      windowHeight: 0,
      excelTableData: [],
      excelHeaders: [],
      searchQuery: "",
      filteredDistributorRecords: []
    };
  },
  mounted() {
    this.updateWindowHeight();
    window.addEventListener("resize", this.updateWindowHeight);
    this.fetch_distributorlist();
  },
  beforeDestroy() {
    window.removeEventListener("resize", this.updateWindowHeight);
  },
  computed: {
    totalCount() {
      return this.filteredDistributorRecords.length;
    },
    pageCount() {
      return Math.ceil(this.filteredDistributorRecords.length / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  watch: {
    currentPage() {
      this.updatePageItems();
    }
  },
  methods: {
    open_editdailog(item) {
      this.componentcheck = 2;
      this.distributoredition = true;
      this.distributorItem = item;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.createdistributors = false;
      this.distributoredition = false;
      this.distributordeletion = false;
      this.fetch_distributorlist();
    },
    open_deletedailog(item) {
      this.componentcheck = 3;
      this.distributordeletion = true;
      this.distributorItem = item;
    },
    add_distributors() {
      this.componentcheck = 1;
      this.createdistributors = true;
    },
    async fetch_distributorlist() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(create_list_edit_delete_asset_distributors, {
          input: {
            organization_id: data.organization.organization_id,
            action_type: "LIST"
          }
        }));
        var response = JSON.parse(result.data.create_list_edit_delete_asset_distributors);
        this.distributorRecords = [];
        this.tableLoading = false;
        if (response.Status == "SUCCESS") {
          this.distributorRecords = response.data;
          this.filterDistributors();
          this.tableLoading = false;
          this.updatePageItems();
        } else {
          this.distributorRecords = [];
          this.tableLoading = false;
        }
      } catch (error) {
        this.distributorRecords = [];
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    onSearchChange() {
      this.currentPage = 1;
      this.filterDistributors();
      this.updatePageItems();
    },
    filterDistributors() {
      if (!this.searchQuery || this.searchQuery.trim() === "") {
        this.filteredDistributorRecords = this.distributorRecords;
      } else {
        const query = this.searchQuery.toLowerCase().trim();
        this.filteredDistributorRecords = this.distributorRecords.filter(distributor => {
          return distributor.asset_distributor_name && String(distributor.asset_distributor_name).toLowerCase().includes(query) || distributor.asset_distributor_code && String(distributor.asset_distributor_code).toLowerCase().includes(query) || distributor.contact_name && String(distributor.contact_name).toLowerCase().includes(query) || distributor.asset_distributor_email && String(distributor.asset_distributor_email).toLowerCase().includes(query) || distributor.full_contact_no && String(distributor.full_contact_no).toLowerCase().includes(query);
        });
      }
    },
    updatePageItems() {
      const startIndex = (this.currentPage - 1) * this.itemsPerPage;
      const endIndex = startIndex + this.itemsPerPage;
      this.paginatedItems = this.filteredDistributorRecords.slice(startIndex, endIndex);
    },
    updateWindowHeight() {
      this.windowHeight = window.innerHeight - 310; // Adjust height as needed
    },
    download_template() {
      const headers = ["Distributor Name*", "Distributor Code", "Territory", "Business Type", "Contact Name", "Email ID", "Country Code", "Contact Number"];
      let fileName = "Distributor_Template.xlsx";
      const ws = XLSX.utils.aoa_to_sheet([headers]);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Sheet1");
      XLSX.writeFile(wb, fileName);
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: "Template downloaded successfully",
        timeout: 5000,
        Top: true
      };
    },
    handleSuccessDistributors({
      results,
      header
    }) {
      this.excelTableData = results;
      this.$router.push("/home/UploadDistributors");
      this.excelHeaders = header;
      let distributorData = {
        excelHeaders: this.excelHeaders,
        excelTableData: this.excelTableData
      };
      this.$store.commit("SetDistributorDetails", distributorData);
    },
    beforeUpload(file) {
      const isLt1M = file.size / 1024 / 1024 < 5;
      if (!isLt1M) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "File size must be smaller than 5MB!",
          timeout: 5000,
          Top: true
        };
        return false;
      }
      return true;
    }
  }
};
